contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // depositAmount: amount to deposit into c from this contract
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // record C's on-chain balance before deposit
        uint beforeC = address(c).balance;
        // deposit into C so that this contract becomes a depositor
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // read recorded credit for this contract (auto getter exists for credit mapping?)
        // Note: credit is not public in C, so we cannot read it. Instead we observe effects via withdraw.
        // We'll record balances before withdraw to reason about change and capture revert.
        uint beforeC_afterDeposit = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General invariant:
        // Let credited = depositAmount (the only way this contract could have obtained credit in this run).
        // If withdrawAll reverted then C's balance and this contract's balance remain as after deposit.
        // If withdrawAll did not revert then this contract's recorded credit must have been cleared to zero
        // and at most credited amount of Ether could have left C (i.e., C's balance decreased by <= credited)
        // and this contract's balance increased by the same amount that left C.
        // We express this as: either reverted and balances unchanged, or not reverted and
        // balance decrease equals this contract's gain and is <= depositAmount, and afterThis >= beforeThis.

        assert(
            (reverted && afterC == beforeC_afterDeposit && afterThis == beforeThis)
            ||
            (!reverted
                && afterThis >= beforeThis
                && beforeC_afterDeposit >= afterC
                && (beforeC_afterDeposit - afterC) == (afterThis - beforeThis)
                && (beforeC_afterDeposit - afterC) <= depositAmount
            )
        );
    }

    // allow receiving ETH if withdrawAll calls back
    receive() external payable {}
}

